class Solution {
    public boolean isNStraightHand(int[] hand, int groupSize) {
        if (hand.length % groupSize != 0) return false;
        java.util.TreeMap<Integer, Integer> map = new java.util.TreeMap<>();
        for (int card : hand) map.merge(card, 1, Integer::sum);
        while (!map.isEmpty()) {
            int first = map.firstKey();
            for (int i = first; i < first + groupSize; i++) {
                if (!map.containsKey(i)) return false;
                if (map.get(i) == 1) map.remove(i);
                else map.merge(i, -1, Integer::sum);
            }
        }
        return true;
    }
}

import java.util.*;

class Solution {
    public boolean isNStraightHand(int[] hand, int groupSize) {
        if (hand.length % groupSize != 0) return false;
        Arrays.sort(hand);
        HashMap<Integer, Integer> freq = new HashMap<>();
        for (int card : hand) freq.put(card, freq.getOrDefault(card, 0) + 1);
        for (int card : hand) {
            if (freq.get(card) == 0) continue;
            for (int j = 0; j < groupSize; j++) {
                int cur = card + j;
                int count = freq.getOrDefault(cur, 0);
                if (count == 0) return false;
                freq.put(cur, count - 1);
            }
        }
        return true;
    }
}
